import { Download } from 'lucide-react';
import { Button } from '../ui/Button.jsx';

/** Downloads the current filtered results as CSV (generated by the API). */
export function ExportButton({ onExport, exporting, disabled }) {
  return (
    <Button
      variant="secondary"
      size="sm"
      icon={Download}
      onClick={onExport}
      loading={exporting}
      loadingText="Exporting…"
      disabled={disabled}
    >
      Export CSV
    </Button>
  );
}
